384		mustQuote(t, e, "B", Quote{Seq: 1, Moment: 1, Price: 5}, 1)
385		mustSetMax(t, e, "B", 100)
386		b2 := mustBuy(t, e, "B", 10, 5)
387		// 先用编号 88 提交一笔会被拒绝的成交（超量）。
388		if _, err := e.Fill(Trade{TradeID: 88, OrderID: b2, Symbol: "B", Side: Buy, Price: 5, Qty: 99}); err == nil {
389			t.Fatal("超量成交应拒绝")
390		}
391		// 编号 88 未被占用，修正数量后提交成功。
392		if _, err := e.Fill(Trade{TradeID: 88, OrderID: b2, Symbol: "B", Side: Buy, Price: 5, Qty: 2}); err != nil {
393			t.Fatalf("被拒绝编号应可复用: %v", err)
394		}
395	}
396	
397	func TestLowerMaxPositionCancelsLastBuys(t *testing.T) {
398		e, _ := NewEngine(1000)
399		mustSetMax(t, e, "A", 10)
400		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: 10}, 1)
401	
402		b1 := mustBuy(t, e, "A", 3, 10) // 最早接受，占用 30
403		b2 := mustBuy(t, e, "A", 3, 10)
404		b3 := mustBuy(t, e, "A", 3, 10) // 最后接受，持仓占用共 9
405	
406		// b1 部分成交 2 股 @9：现金 -18，持仓 2，买单剩余额度 7。
407		if _, err := e.Fill(Trade{TradeID: 1, OrderID: b1, Symbol: "A", Side: Buy, Price: 9, Qty: 2}); err != nil {
408			t.Fatal(err)
409		}
410		// 此时 持仓 2 + 买单剩余 7 = 9。下调限额到 5：
411		// 先取消 b3（剩余 3）→ 2+4=6 仍超；再取消 b2（剩余 3）→ 2+1 满足。
412		canceled := mustSetMax(t, e, "A", 5)
413		if len(canceled) != 2 || canceled[0] != b3 || canceled[1] != b2 {
414			t.Fatalf("应按最后接受顺序撤销 b3,b2，实际 %v", canceled)
415		}
416		if e.ReservedCash() != 10 { // b1 剩余 1 股 × 10
417			t.Fatalf("撤单释放现金错误: reserved=%d", e.ReservedCash())
418		}
419		if e.Cash() != 1000-18 {
420			t.Fatalf("撤单不得触动已成交金额: cash=%d", e.Cash())
421		}
422		o1, _ := e.Order(b1)
423		if o1.Status != StatusPartial {
424			t.Fatal("b1 应保持部分成交")
425		}
426	
427		// 再下调到 1：持仓 2 已超限，撤掉全部未成交买单（b1 剩余 1）。
428		canceled = mustSetMax(t, e, "A", 1)
429		if len(canceled) != 1 || canceled[0] != b1 {
430			t.Fatalf("持仓超限时应撤销 b1，实际 %v", canceled)
431		}
432		if e.ReservedCash() != 0 || e.Position("A") != 2 {
433			t.Fatalf("撤销全部买单后 reserved=0、持仓保留: reserved=%d pos=%d", e.ReservedCash(), e.Position("A"))
434		}
435		// 持仓超限：后续买单拒绝。
436		if _, err := e.Buy("A", 1, 10); err == nil {
437			t.Fatal("持仓超限时新买单必须拒绝")
438		}
439		// 仍允许卖出，不自动平仓。
440		sid := mustSell(t, e, "A", 2, 10)
441		if _, err := e.Fill(Trade{TradeID: 2, OrderID: sid, Symbol: "A", Side: Sell, Price: 10, Qty: 2}); err != nil {
442			t.Fatal(err)
443		}
444		if e.Position("A") != 0 || e.Cash() != 1000-18+20 {
445			t.Fatalf("卖出后状态错误: pos=%d cash=%d", e.Position("A"), e.Cash())
446		}
447	
448		// 负限额报错。
449		if _, err := e.SetMaxPosition("A", -1); err == nil {
450			t.Fatal("负最大持仓量必须报错")
451		}
452	}
453	
454	func TestRecordsSnapshotsAndImmutability(t *testing.T) {
455		e, _ := NewEngine(1000)
456	
457		// 无报价、无限额时的拒绝记录：快照明确为空。
458		_, err := e.Buy("X", 1, 10)
459		expectErr(t, err, "尚未设置最大持仓量")
460		recs := e.Records()
461		if len(recs) != 1 || recs[0].Kind != RecordRejected || recs[0].QuoteValid || recs[0].MaxPositionValid {
462			t.Fatalf("拒绝记录快照应为空: %+v", recs)
463		}
464		if recs[0].Reason == "" {
465			t.Fatal("拒绝记录必须包含具体原因")
466		}
467	
468		mustSetMax(t, e, "A", 10)
469		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 100, Price: 10}, 1)
470		id := mustBuy(t, e, "A", 4, 10)
471	
472		// 接受记录快照：报价 seq1 与限额 10。
473		rec := e.Records()[1]
474		if rec.Kind != RecordAccepted || !rec.QuoteValid || rec.QuoteSeq != 1 || rec.QuoteMoment != 100 ||
475			rec.QuotePrice != 10 || !rec.MaxPositionValid || rec.MaxPosition != 10 {
476			t.Fatalf("接受记录快照错误: %+v", rec)
477		}
478	
479		if _, err := e.Fill(Trade{TradeID: 1, OrderID: id, Symbol: "A", Side: Buy, Price: 9, Qty: 2}); err != nil {
480			t.Fatal(err)
481		}
482		mustQuote(t, e, "A", Quote{Seq: 2, Moment: 200, Price: 20}, 1)
483		mustSetMax(t, e, "A", 99)
484	
485		// 后续报价与限额变化不能改写历史记录，且成交金额不重算。
486		rec = e.Records()[2]
487		if rec.Kind != RecordFilled || rec.QuoteSeq != 1 || rec.QuotePrice != 10 || rec.MaxPosition != 10 {
488			t.Fatalf("成交记录被后续变化改写: %+v", rec)
489		}
490		if e.Cash() != 1000-18 {
491			t.Fatalf("报价变化不得重算已成交金额: cash=%d", e.Cash())
492		}
493	
494		// 限额下调触发的撤销记录带原因与当时快照（seq2, 限额99）。
495		canceled := mustSetMax(t, e, "A", 1) // 持仓 2 超限，撤销剩余买单 2
496		if len(canceled) != 1 {
497			t.Fatalf("应撤销 1 单，实际 %v", canceled)
498		}
499		rec = e.Records()[len(e.Records())-1]
500		if rec.Kind != RecordCanceled || rec.Reason == "" || !rec.QuoteValid ||
501			rec.QuoteSeq != 2 || rec.QuotePrice != 20 || rec.MaxPosition != 1 {
502			t.Fatalf("限额撤销记录快照/原因错误: %+v", rec)
503		}
504		if rec.Remaining != 2 || rec.Filled != 2 {
505			t.Fatalf("撤销记录应区分已成交 2 与剩余 2: %+v", rec)
506		}
507	
508		// 状态枚举中文可辨识。
509		if StatusPending.String() != "待成交" || StatusPartial.String() != "部分成交" ||
510			StatusFilled.String() != "全部成交" || StatusCanceled.String() != "已撤销" {
511			t.Fatal("订单状态文案错误")
512		}
513	}
514	
515	func TestCancelUnfilledBuyReleasesCash(t *testing.T) {
516		e, _ := NewEngine(100)
517		mustSetMax(t, e, "A", 100)
518		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: 10}, 1)
519		id := mustBuy(t, e, "A", 5, 10)
520		if err := e.Cancel(id); err != nil {
521			t.Fatal(err)
522		}
523		if e.Cash() != 100 || e.ReservedCash() != 0 || e.AvailableCash() != 100 {
524			t.Fatalf("撤销未成交买单应全额释放现金: cash=%d reserved=%d", e.Cash(), e.ReservedCash())
525		}
526		o, _ := e.Order(id)
527		if o.Status != StatusCanceled || o.Remaining() != 0 {
528			t.Fatalf("订单应标记撤销: %+v", o)
529		}
530	}
