532	func TestGapAllowsSellCancelAndFill(t *testing.T) {
533		e, _ := NewEngine(1000)
534		mustSetMax(t, e, "A", 100)
535		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: 10}, 1)
536		bid := mustBuy(t, e, "A", 10, 10)
